STORY = [('kuroki', '黒木香って？誰のことですか？', 'Kaoru Kuroki? Who is that?', [(211, '黒木 香って'), (212, '誰のことですか')], ''), ('reika', 'それにしても傑作だったよね。記者の人たちみんなポカンとしてた。', 'Still, that was priceless! Every one of those reporters stood there dumbfounded.', [(221, 'それにしても傑作だったよね'), (222, '記者の人たち みんな ポカンとしてた')], ''), ('kuroki', '順子さんもなかなかの演技でしたよ。', 'That was some pretty fine acting from you too.', [(223, '順子さんも なかなかの演技でしたよ')], ''), ('reika', 'これでまた記憶喪失とか好き勝手言うんだろうな。ホント世間ってやつは。', "Now they'll probably make up wild stories about amnesia. Honestly, the public never stops.", [(226, 'これでまた 記憶喪失とか 好き勝手 言うんだろうな'), (227, 'ホント 世間ってやつは')], ''), ('kuroki', 'でもさっき記者に言ったあれ、まんざらウソじゃないかも。誰のことですかって。', 'Still, what I said to the reporters earlier might not be entirely a lie—asking who that was.', [(229, 'でも さっき記者に言った あれ まんざらウソじゃないかも'), (230, '誰のことですか')], ''), ('kuroki', '少しずつ黒木香が薄まってたの。あの日からずっと、一日一日。', 'Little by little, Kaoru Kuroki has been fading away—day by day ever since that day.', [(231, '少しずつ 黒木 香が薄まってたの'), (232, 'あの日から ずっと 一日一日')], ''), ('kuroki', 'きっとこのタクシーに乗って家に着いたら、完全に消えちゃうと思う。', 'Once I ride this taxi and reach home, I think she will vanish completely.', [(233, 'きっと このタクシーに乗って 家に着いたら'), (234, '完全に消えちゃうと思う')], ''), ('kuroki', '最後に見届けるのが順子さんでよかった。ありがとう、順子さん大好き。', "I'm glad you were the last one to see me off. Thank you—I love you.", [(236, '最後に見届けるのが 順子さんでよかった'), (237, 'ありがとう'), (238, '順子さん 大好き')], ''), ('reika', '私も。', 'I love you too.', [(239, '私も')], ''), ('kayo', 'いい街だったのね。帰ったらごはん食べましょう、お母さん作るから。', "It was a lovely city, wasn't it? Let's eat dinner once we get home—Mom will cook for you.", [(241, 'いい街だったのね'), (242, '帰ったら ごはん食べましょう'), (243, 'お母さん 作るから')], ''), ('kuroki', 'ごめんなさい、たくさん。', "I'm so sorry for everything.", [(244, 'ごめんなさい たくさん')], ''), ('kayo', 'いてくれるだけで十分。', 'Just having you here alive is more than enough.', [(245, 'いてくれるだけで 十分')], '')]
